import{_ as o,o as a,a as e,a3 as r}from"./chunks/framework.CkbYhqXo.js";const c=JSON.parse('{"title":"Конструктор","description":"Конструктор Stuzhik: собрать модпак без установки — состав, каталог, проверка совместимости и граф зависимостей, конфиги, экспорт в .stzhk и тестовый запуск.","frontmatter":{"description":"Конструктор Stuzhik: собрать модпак без установки — состав, каталог, проверка совместимости и граф зависимостей, конфиги, экспорт в .stzhk и тестовый запуск.","head":[["meta",{"name":"keywords","content":"stuzhik конструктор, создать модпак, сборка без установки, проверка совместимости модов, граф зависимостей, экспорт stzhk"}]]},"headers":[],"relativePath":"guide/builder.md","filePath":"guide/builder.md"}'),u={name:"guide/builder.md"};function i(l,t,n,q,h,d){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="конструктор" tabindex="-1">Конструктор <a class="header-anchor" href="#конструктор" aria-label="Permalink to &quot;Конструктор&quot;">​</a></h1><p>&quot;Конструктор&quot; в сайдбаре — место, где модпак собирается как проект, без установки. Пока проект не превращён в экземпляр, на диск не ставится ни Minecraft, ни моды: в проекте хранятся список модов с закреплёнными версиями, ресурспаки, шейдеры и конфиги.</p><p>Готовый проект можно поставить себе экземпляром, выгрузить в <code>.stzhk</code> или опробовать тестовым запуском.</p><h2 id="новыи-проект" tabindex="-1">Новый проект <a class="header-anchor" href="#новыи-проект" aria-label="Permalink to &quot;Новый проект&quot;">​</a></h2><ol><li>Сайдбар → &quot;Конструктор&quot; → &quot;Создать проект&quot;</li><li>Название, версия Minecraft и загрузчик</li><li>&quot;Создать&quot;</li></ol><p>Модпак Modrinth можно сделать проектом: кнопка &quot;Импорт .mrpack&quot;.</p><h2 id="состав" tabindex="-1">Состав <a class="header-anchor" href="#состав" aria-label="Permalink to &quot;Состав&quot;">​</a></h2><p>Вкладка &quot;Состав&quot; — то, что войдёт в модпак, по разделам &quot;Моды&quot;, &quot;Ресурспаки&quot;, &quot;Шейдеры&quot;. Для каждого мода:</p><ul><li><strong>Включён / выключен</strong> — выключенный остаётся в проекте, в экземпляр ляжет выключенным, в экспорт не попадёт</li><li><strong>Обязательный / необязательный</strong> — пометка для тех, кто будет ставить модпак</li><li><strong>Сторона</strong> — &quot;Клиент&quot;, &quot;Сервер&quot; или &quot;Обе&quot;</li></ul><p>Сверху — поиск по составу и общий вес модпака.</p><h2 id="каталог" tabindex="-1">Каталог <a class="header-anchor" href="#каталог" aria-label="Permalink to &quot;Каталог&quot;">​</a></h2><p>Вкладка &quot;Каталог&quot; — поиск по Modrinth и CurseForge, сразу под версию Minecraft и загрузчик проекта. Обязательные зависимости добавляются вместе с модом, а мод, который не встанет рядом с уже добавленными, не добавится — лаунчер скажет, с чем он конфликтует.</p><h2 id="совместимость" tabindex="-1">Совместимость <a class="header-anchor" href="#совместимость" aria-label="Permalink to &quot;Совместимость&quot;">​</a></h2><p>Проверка работает без установки — по тому, что версии модов объявили на Modrinth и CurseForge, и по описанию внутри самого <code>.jar</code>, где записаны допустимые версии других модов.</p><ul><li><strong>&quot;Проблемы&quot;</strong> — чего не хватает (недостающую зависимость можно добавить одной кнопкой) и что не встанет вместе. Моды, положенные файлом или без версии, проверить нельзя — они перечислены отдельно</li><li><strong>&quot;Граф зависимостей&quot;</strong> — связи модов проекта: кто от кого зависит, что с чем несовместимо</li></ul><h2 id="конфиги" tabindex="-1">Конфиги <a class="header-anchor" href="#конфиги" aria-label="Permalink to &quot;Конфиги&quot;">​</a></h2><p>Вкладка &quot;Конфиги&quot; — файлы настроек модов, которые поедут вместе с модпаком: в экспорт и в экземпляр. Правка прямо в лаунчере или &quot;Открыть в VS Code&quot;, у каждого файла история изменений: видно, что поменялось, и можно вернуть прежнее.</p><h2 id="готовыи-модпак" tabindex="-1">Готовый модпак <a class="header-anchor" href="#готовыи-модпак" aria-label="Permalink to &quot;Готовый модпак&quot;">​</a></h2><ul><li><strong>&quot;Тестовый запуск&quot;</strong> — быстро создаёт экземпляр <code>[TEST] &lt;название&gt;</code> с модами и конфигами проекта, чтобы опробовать модпак в игре</li><li><strong>Экспорт → &quot;Создать экземпляр&quot;</strong> — то же, но со своим именем</li><li><strong>Экспорт → &quot;Экспорт в .stzhk&quot;</strong> — файл модпака. С галочкой &quot;Встроить моды в архив&quot; файл больше, зато при установке не нужен интернет; без неё моды скачиваются при установке</li></ul><p>Название, версия, автор и описание модпака — во вкладке &quot;Настройки&quot;.</p><h2 id="собрать-вместе-с-друзьями" tabindex="-1">Собрать вместе с друзьями <a class="header-anchor" href="#собрать-вместе-с-друзьями" aria-label="Permalink to &quot;Собрать вместе с друзьями&quot;">​</a></h2><p>С включёнными экспериментальными функциями (Настройки → Общие → &quot;Экспериментальные функции&quot;) у проекта появляется кнопка &quot;Собрать вместе&quot;: друзья видят проект в &quot;Друзьях&quot; и правят его вместе с вами, а ставить его никому не нужно. Подробнее — <a href="/guide/connect.html#coop-build">Совместная сборка</a>.</p><h2 id="что-дальше" tabindex="-1">Что дальше? <a class="header-anchor" href="#что-дальше" aria-label="Permalink to &quot;Что дальше?&quot;">​</a></h2><ul><li><a href="/guide/modpacks.html">Модпаки</a> — установка, обновление и форматы</li><li><a href="/guide/collections.html">Сборки модов</a> — набор модов, который подбирается под любую версию</li></ul>',24)])])}const p=o(u,[["render",i]]);export{c as __pageData,p as default};
